  vehicle_id UUID REFERENCES vehicles(id),
  title TEXT NOT NULL,
  price INT,
  createdAt TIMESTAMP
);

alter policy "profiles_access" on profiles
  using (
    uid = auth.uid() OR
    uid IN (SELECT seller_uid FROM listings WHERE status = 'active')
  );

