// Admin 登入與權限檢查
import { getAuth, onAuthStateChanged } from 'firebase/auth';

onAuthStateChanged(getAuth(), async user => {
  if (!user) {
    return location.href = '/login';
  }
  const { claims } = await user.getIdTokenResult();
  if (!claims.admin) {
    document.body.innerHTML = '<h1>無權限存取此頁面</h1>';
    return;
  }
  initializeDashboard();
});

